@import url('https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600;800&display=swap');

:root {
  --bg-pure: oklch(0.05 0 0);
  --nebula-blue: oklch(65% 0.25 280);
  --cosmic-violet: oklch(60% 0.2 310);
  --surface-base: oklch(0.15 0.02 280 / 0.4);
  --surface-highlight: oklch(0.9 0.02 280 / 0.08);
  --text-primary: oklch(0.98 0 0);
  --text-muted: oklch(0.6 0.05 280);
  --mouse-x: 50%;
  --mouse-y: 50%;
  color-scheme: dark light;
}.sc-tw [data-theme="light"]{
  --bg-pure: oklch(0.98 0.01 280);
  --surface-base: oklch(0.95 0.02 280 / 0.6);
  --surface-highlight: oklch(1 0 0 / 0.5);
  --text-primary: oklch(0.1 0.02 280);
  --text-muted: oklch(0.4 0.05 280);
}.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
  animation: 1s cubic-bezier(0.16, 1, 0.3, 1) both blend-fade;
}

@keyframes blend-fade {0%{ opacity: 0; filter: blur(20px) saturate(0); }100%{ opacity: 1; filter: blur(0) saturate(100%); }
}.sc-tw *{
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}.sc-tw{
  background-color: var(--bg-pure);
  color: var(--text-primary);
  font-family: 'Inter', sans-serif;
  overflow-x: hidden;
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.8s ease;
}.sc-tw .atmospheric-portal{
  position: fixed;
  bottom: -20vh;
  right: -15vw;
  width: 90vw;
  height: 90vw;
  border-radius: 50%;
  overflow: hidden;
  filter: none;
  opacity: 1;
  mix-blend-mode: normal;
  pointer-events: none;
  z-index: -1;
  will-change: transform;
  transform: translate3d(0,0,0);
}.sc-tw [data-theme="light"] .atmospheric-portal{
  mix-blend-mode: normal;
  opacity: 1;
}.sc-tw .atmospheric-portal video{
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: none;
}

@keyframes scroll-shimmer {to{ background-position: 200% center; }
}.sc-tw .kinetic-text{
  background: linear-gradient(
    110deg,
    var(--text-primary) 0%,
    var(--nebula-blue) 25%,
    var(--text-primary) 50%,
    var(--cosmic-violet) 75%,
    var(--text-primary) 100%
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: scroll-shimmer linear;
  animation-timeline: scroll(root block);
}.sc-tw .liquid-obsidian{
  background: var(--surface-base);
  backdrop-filter: blur(40px) saturate(180%);
  -webkit-backdrop-filter: blur(40px) saturate(180%);
  box-shadow: 
    inset 0 1px 1px var(--surface-highlight),
    inset 0 -2px 10px rgba(0, 0, 0, 0.4),
    0 30px 60px rgba(0, 0, 0, 0.4);
  border-radius: 2rem;
  position: relative;
  isolation: isolate;
}.sc-tw .liquid-obsidian::before{
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: radial-gradient(
    800px circle at var(--mouse-x) var(--mouse-y),
    var(--nebula-blue),
    transparent 40%
  );
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0.3;
  pointer-events: none;
  transition: opacity 0.5s ease;
}.sc-tw .liquid-obsidian:hover::before{
  opacity: 1;
}.sc-tw .frosted-ether{
  background: radial-gradient(circle at top left, var(--surface-highlight), transparent 70%);
  backdrop-filter: blur(60px);
  -webkit-backdrop-filter: blur(60px);
  box-shadow: 
    inset 0 2px 4px rgba(255, 255, 255, 0.1),
    inset 0 -2px 20px rgba(0, 0, 0, 0.5),
    0 15px 35px rgba(0, 0, 0, 0.3);
  border-radius: 1.5rem;
  position: relative;
  overflow: hidden;
}.sc-tw .mercury-btn{
  position: relative;
  overflow: hidden;
  border-radius: 999px;
  padding: 1.2rem 2.5rem;
  color: #000;
  font-weight: 600;
  letter-spacing: -0.01em;
  background: linear-gradient(180deg, #ffffff, #c8c8dc);
  box-shadow: 
    inset 0 2px 2px rgba(255, 255, 255, 1),
    inset 0 -4px 8px rgba(0, 0, 0, 0.2),
    0 10px 20px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(255, 255, 255, 0.2);
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: none;
}.sc-tw [data-theme="light"] .mercury-btn{
  background: linear-gradient(180deg, #111, #333);
  color: #fff;
  box-shadow: 
    inset 0 2px 2px rgba(255, 255, 255, 0.2),
    inset 0 -4px 8px rgba(0, 0, 0, 0.8),
    0 10px 20px rgba(0, 0, 0, 0.1);
}.sc-tw .mercury-btn::after{
  content: '';
  position: absolute;
  inset: -50%;
  background: radial-gradient(circle at var(--mouse-x) var(--mouse-y), rgba(255,255,255,0.8), transparent 50%);
  opacity: 0;
  transition: opacity 0.3s ease;
  mix-blend-mode: overlay;
  pointer-events: none;
}.sc-tw .mercury-btn:hover{
  transform: translateY(-4px) scale(1.02);
  box-shadow: 
    inset 0 2px 2px rgba(255, 255, 255, 1),
    inset 0 -4px 8px rgba(0, 0, 0, 0.1),
    0 20px 40px var(--nebula-blue),
    0 0 0 1px rgba(255, 255, 255, 0.5);
}.sc-tw [data-theme="light"] .mercury-btn:hover{
  box-shadow: 
    inset 0 2px 2px rgba(255, 255, 255, 0.2),
    inset 0 -4px 8px rgba(0, 0, 0, 0.8),
    0 20px 40px var(--nebula-blue);
}.sc-tw .mercury-btn:hover::after{
  opacity: 1;
}.sc-tw .reveal-scroll{
  opacity: 0;
  transform: translateY(40px) scale(0.98);
  filter: blur(10px);
  animation: reveal-keyframe linear forwards;
  animation-timeline: view();
  animation-range: entry 10% cover 30%;
}

@keyframes reveal-keyframe {to{
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}.sc-tw .bento-grid{
  container-type: inline-size;
  container-name: bento;
}.sc-tw .micro-label{
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--text-muted);
  font-weight: 500;
}.sc-tw .theme-trigger{
  width: 48px;
  height: 24px;
  border-radius: 999px;
  background: var(--surface-highlight);
  backdrop-filter: blur(10px);
  position: relative;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: border-color 0.3s;
}.sc-tw .theme-trigger::before{
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--text-primary);
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}.sc-tw [data-theme="light"] .theme-trigger::before{
  transform: translateX(24px);
